"use client";
import {useEffect,useRef,useState} from 'react';import {hotelClient,hotelRpc,usd} from '@/lib/pilot';import type {HandoffScope} from '@/lib/cashier-handoff';
export function CashierBankAccountingStatus({scope,statement,amount,bank}:{scope:HandoffScope;statement:string;amount:string;bank:string}){
 const [status,setStatus]=useState<{posted:string;unposted:string;voided:boolean}|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const alive=useRef(false),lock=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 async function load(){if(lock.current)return;lock.current=true;setBusy(true);setError('');setStatus(null);try{const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Refresh statements.');const response=await hotelRpc('bank_statement_accounting_status',{p_tenant:scope.tenant,p_property:scope.property,p_statement:statement});if(!response||typeof response!=='object'||Array.isArray(response))throw Error('Invalid statement accounting status.');const v=response as Record<string,unknown>;const expected=(BigInt(amount)<BigInt(0)?-BigInt(amount):BigInt(amount)).toString();
 if(v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.statement_id!==statement||v.bank_id!==bank||v.amount_minor!==expected||v.direction!==(BigInt(amount)>BigInt(0)?'credit':'debit')||typeof v.posted_minor!=='string'||! /^(0|[1-9][0-9]{0,11})$/.test(v.posted_minor)||typeof v.unposted_minor!=='string'||! /^(0|[1-9][0-9]{0,11})$/.test(v.unposted_minor)||BigInt(v.posted_minor)+BigInt(v.unposted_minor)!==BigInt(expected)||typeof v.voided!=='boolean'||v.fully_posted!==(!v.voided&&v.unposted_minor==='0')||v.bank_verified!==false)throw Error('Statement accounting totals changed.');const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Refresh statements.');if(alive.current)setStatus({posted:v.posted_minor,unposted:v.unposted_minor,voided:v.voided});
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to check accounting.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <div><button type="button" disabled={busy} onClick={()=>void load()}>Check ledger status</button>{error&&<p role="alert">{error}</p>}{status&&<p role="status">{status.voided?'Voided statement. ':''}Posted: {usd(Number(status.posted))}. Unposted: {usd(Number(status.unposted))}.</p>}</div>
}
